import 'package:flutter/material.dart';
import 'package:quickfix/core/theme/app_theme.dart';
import 'package:quickfix/core/widgets/app_card.dart';

/// Deployment-specific data practices for this prototype, not generic claims
/// of legal compliance. Keep aligned with AccountDeletionService and the proxy.
class LegalScreen extends StatelessWidget {
  final int initialTab;
  const LegalScreen({super.key, this.initialTab = 0}) : assert(initialTab >= 0 && initialTab < 2);
  static const _terms = <(String, String)>[
    ('About this demo', 'QuickFix connects clients and local service workers. This is a prototype, not an emergency service or a guarantee of workmanship. Agree scope, timing, safety and price directly before work starts. Use emergency services for urgent danger.'),
    ('Accounts and contact details', 'Use accurate details and protect your password. Worker profiles describe the services offered; a listing is not a professional licence. Admin accounts are managed separately. You are responsible for the content you submit.'),
    ('Jobs, location and photos', 'A posted job includes a description, category, budget, schedule, address and location pin. Location access is optional for browsing and chat; posting needs a one-shot pin. There is no continuous or background tracking. Map buttons open a separate maps application. Images currently stay on the device that captured them and may not display for other users.'),
    ('Reviews, ranks and identity', 'Reviews must reflect genuine work. Translation and summaries can be inaccurate; consult original reviews. Ranks describe completed-work volume over the trailing year, not licences or background checks. A Verified identity status means an admin recorded a separate manual check. Device-local CNIC/selfie capture is a labelled demo and is not production remote identity verification.'),
    ('Simulated payments', 'Current payment actions create simulated receipts for demonstrations. QuickFix does not collect card details or transfer real funds in this flow. A paid label is not proof of a real bank transfer. Agree and verify any real-world payment separately.'),
    ('Safe use and moderation', 'Do not post abusive, fraudulent or unlawful material. Avoid placing identity documents, financial secrets or other sensitive information in public job details, reviews or chat. Verification has its own consent and private references. Use Report on a job or worker page for account-related abuse; admins review submitted reports manually.'),
    ('Account and data help', 'For a forgotten password, return to Sign in and use Forgot password. Use Profile → Settings for review language, these data practices and account deletion. Complete or cancel active assigned work before deletion. This prototype has no in-app live support desk or guaranteed response time; contact the project operator through the channel through which you received this demo.'),
  ];
  static const _privacy = <(String, String)>[
    ('Account and profile data', 'Firebase Authentication handles email/password credentials. Firestore users stores account ID, name, email, phone, role, avatar file reference, preferred review language and saved worker IDs. Bookmarks follow the prototype’s signed-in profile-access rules, not a private contact-vault guarantee. Workers adds skills, spoken languages, availability, budget range, service radius, rating and completed-work counts. We do not write plaintext passwords to Firestore.'),
    ('Jobs, reviews, messages and receipts', 'Firestore jobs and jobRequests contain participant IDs, work details, addresses/pins, schedules, budgets, status and photo references. Reviews contain ratings, original text/language and cached translations. Conversations/messages contain participant IDs, text, timestamps, read state and any explicitly shared location. Payments stores simulated receipt IDs, participants, amounts, job references and status. Reports stores target/reporter references, reasons, details and moderation status. Notifications stores generic in-app update text, read state, dates and source reference IDs. Your notification preferences filter the in-app list/badge, not push or email; records may still be generated when hidden.'),
    ('Visibility and private verification', 'Signed-in users can browse user/worker profiles, jobs and reviews. Chat content and simulated receipts are limited to their participants and admins; reports are available to the reporter and admins. Verification photo references, consent and reviewer notes are in owner/admin-only workerVerifications documents. Other users see verification status/dates, not CNIC/selfie references or rejection notes. Admin access is for operating and moderating the service.'),
    ('One-shot location, not tracking', 'With permission, a single position is used to find nearby workers, pin a posted job or share a position you choose in chat. Job pins and shared positions are stored with the job/message. Saved address-book labels, addresses and pins are in owner/admin-only users/{uid}/private/addressBook, and are copied to a job only when you choose and submit them. There is no background location subscription or continuous movement history. Denying permission still permits browsing; system settings can change access later.'),
    ('Device-local images and caches', 'Job photos, avatars and verification captures are copied into the app documents directory on the capturing device. Firestore stores file references, not image uploads; Firebase Storage is not used. Imported legacy avatar URLs can load from their remote image host, which may receive ordinary network request data. Remote users/admins cannot fetch device-local files. Verification reads are confined to the account’s local proof directory. SharedPreferences stores onboarding/build flags and cached job/category data; Firebase may also cache reads. Local copies are not a secure document-sharing service.'),
    ('Google Cloud Translation and summaries', 'When the translation proxy is configured, review text and the selected target language are sent to that backend, which uses Google Cloud Translation. The optional summary proxy receives review text, ratings, source languages, target language and worker display name; it uses translation and extractive summarization. Without a usable proxy, originals/offline extracts remain available, not guaranteed translated output. Do not include secrets in reviews. Proxy/provider logs and retention depend on the operator’s deployment; the mobile app does not erase those logs.'),
    ('Retention and account deletion', 'Profile → Settings → Delete account requires typed confirmation and password reauthentication before destructive cleanup. It removes user/worker profiles, private verification/address-book records, posted non-retained jobs, reviews written by you or about your worker profile, job applications, your notification inbox and chats involving you, then deletes the Auth account. The current device’s app-managed photo/SharedPreferences cleanup is part of the flow. Legacy job/avatar cache folders are shared across accounts on this device and are cleared; other accounts’ verification folders are left alone. Active assigned/in-progress work blocks deletion. A failed or timed-out cleanup may be partial and must be resumed; it is not reported as complete.'),
    ('What can remain', 'Anonymous aggregate ratings/counts may remain after individual review records are removed. Completed jobs needed for the other party’s history and simulated receipts are retained with your account ID replaced by a shared deleted-account label and identifying job fields removed. Document/receipt reference IDs remain, including any imported legacy IDs; this is de-identification, not guaranteed irreversible anonymity. Moderation reports may remain as submitted for admin review, including references/free text. A private, minimal accountDeletions progress/tombstone record retains an account ID and timing/status for retry and to block stale-session writes. This demo has no automatic expiry for those operational/moderation records; administrators must review and remove them. No statutory retention period or compliance certification is claimed.'),
    ('Limits of erasure and your choices', 'Account deletion does not remotely wipe other devices, downloaded/screenshot copies, quoted free text, generic notification references retained in other recipients’ inboxes, provider logs or deployment backups. Uninstalling alone does not remove Firestore data. Camera/gallery originals, platform/plugin caches and Firebase SDK persistence are not forcibly wiped by this flow. Other-device caches may remain until that device reconnects or clears app data. Onboarding/build flags may stay on this device; they contain no account identity. You can decline location, avoid optional identity capture, keep originals visible and choose a review translation language. Contact the demo operator for a manual data or moderation review.'),
  ];
  Widget _clauses(String key, List<(String, String)> clauses) => ListView.builder(key: PageStorageKey(key), padding: const EdgeInsets.all(16),
    itemCount: clauses.length + 1, itemBuilder: (context, index) {
      if (index == 0) return const Padding(padding: EdgeInsets.only(bottom: 16), child: Text('Updated 18 October 2026 • QuickFix prototype', style: TextStyle(fontSize: 12, color: AppTheme.textMuted)));
      final clause = clauses[index - 1];
      return Padding(padding: const EdgeInsets.only(bottom: 12), child: AppCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text('$index. ${clause.$1}', style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w600, color: AppTheme.textDark)),
        const SizedBox(height: 10), Text(clause.$2, style: const TextStyle(fontSize: 13, height: 1.5, color: AppTheme.textMuted)),
      ])));
    });
  @override
  Widget build(BuildContext context) => DefaultTabController(length: 2, initialIndex: initialTab, child: Scaffold(
    backgroundColor: AppTheme.bgLight,
    appBar: AppBar(title: const Text('Terms & Privacy', maxLines: 1, overflow: TextOverflow.ellipsis), bottom: const TabBar(tabs: [Tab(key: Key('legal-terms-tab'), text: 'Terms'), Tab(key: Key('legal-privacy-tab'), text: 'Privacy')])),
    body: SafeArea(child: TabBarView(children: [_clauses('terms-clauses', _terms), _clauses('privacy-clauses', _privacy)])),
  ));
}
